// Auto-generated ObjectId
const id = new ObjectId();
console.log(id.toString());              // "6752ab3f1234567890abcdef"
console.log(id.getTimestamp());          // Date object — when it was created

// Extract creation timestamp from any ObjectId
const doc = await users.findOne({ name: 'Alice' });
console.log(doc._id.getTimestamp());     // When Alice's document was created

// Custom _id (e.g., use email as ID)
await users.insertOne({
  _id: 'alice@example.com',  // custom string _id
  name: 'Alice'
});
// Now you can find Alice without knowing her ObjectId:
await users.findOne({ _id: 'alice@example.com' });

// BAD: dates as strings — cannot sort, range query, or extract month
await events.insertOne({
  name: 'Conference',
  date: '2026-06-15'  // string — will sort lexicographically, not chronologically
});

// GOOD: use BSON Date
await events.insertOne({
  name: 'Conference',
  date: new Date('2026-06-15')  // ISODate — sortable, comparable, math-friendly
});

// Now you can query date ranges correctly:
const upcoming = await events.find({
  date: { $gte: new Date() }  // all events from now onwards
}).sort({ date: 1 }).toArray();

// Extract year from date in aggregation:
db.events.aggregate([
  { $project: { year: { $year: '$date' }, name: 1 } }
]);

