// Simulate BSON type handling in JavaScript
// (In real MongoDB, the driver handles this automatically)

// Simulate ObjectId
function createObjectId() {
  const timestamp = Math.floor(Date.now() / 1000).toString(16).padStart(8, '0');
  const random = Math.random().toString(16).slice(2, 12).padStart(10, '0');
  const counter = Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0');
  return timestamp + random + counter;
}

// Create a document with proper types
const product = {
  _id: createObjectId(),
  name: 'Wireless Headphones',
  price: 2499.99,          // Double
  inStock: true,           // Boolean
  tags: ['audio', 'wireless', 'bluetooth'],  // Array
  specs: {                 // Embedded document
    brand: 'SoundMax',
    battery: '30h'
  },
  createdAt: new Date()    // Date
};

console.log('Product:', JSON.stringify(product, null, 2));
console.log('\n_id prefix (timestamp):', product._id.slice(0, 8));
console.log('Created at:', product.createdAt.toISOString());
